package com.nextgen.store.media;
import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.nio.file.Files;
@RestController @RequestMapping("/api/v1/images") public class ImageController { private final ImageStorageService storage; public ImageController(ImageStorageService storage){this.storage=storage;} @PostMapping @PreAuthorize("hasRole('ADMIN')") public java.util.Map<String,String> upload(@RequestParam("file") MultipartFile file){String key=storage.store(file);return java.util.Map.of("key",key,"url","/api/v1/images/"+key);} @GetMapping("/{key}") public ResponseEntity<byte[]> get(@PathVariable String key)throws Exception{var r=storage.load(key);String type=r.contentType()==null?"application/octet-stream":r.contentType();return ResponseEntity.ok().contentType(MediaType.parseMediaType(type)).cacheControl(CacheControl.maxAge(java.time.Duration.ofDays(30)).cachePublic()).body(Files.readAllBytes(r.path()));} }
